      const W = Math.max(1, Math.round(img.naturalWidth * k)), H = Math.max(1, Math.round(img.naturalHeight * k)), band = lines ? jfStampLayout(W, lines) : null;
      c.width = W; c.height = H + (band ? band.h : 0);
